cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,16))-{6,10,11,12,13,14},same
notes={1:'Abertura dos Ofícios, treino e quadro do projeto.',2:'Teste, etiquetas, reparo interrompido e ajuda.',3:'Quadro de reparo; treinamentos sem regra aprovada; abertura das ferramentas.',4:'Usar e identificar ferramentas; criar a ficha.',5:'Desgaste e quadro do objeto perigoso.',6:'Fim das ferramentas; abertura do Anel e quadro da ficha experimental.',7:'Grau 3, exemplo de uso, identificação e início do contrato.',8:'Contrato, trabalho, falha e entrega.',9:'Registro do Anel; abertura do Cofre e quadro de conferência.',10:'Venda e Palavra Empenhada; espaço em branco no pé da página.',11:'Abertura da Pastilha com rótulo e título juntos; quadro do selo.',12:'O que o grupo sabe, retirar, renovar e ingestão.',13:'Destruição e entrega; abertura do Limiar e quadro da cura.',14:'Quadro dos requisitos do feito e XP.',15:'Promoção, quadro dos registros e registro final.'}
save('revisao-final.json',{'registro':127,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das seis fontes e das regras citadas, seis cópias, remissões, clareza e a frase sobre treinamentos.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura da prova completa, trechos alterados no contexto e varredura de crase, repetições e termos de produção; pente fino.'}],'ajuste_de_diagramacao':'Rótulo de cada caso preso ao título; o caso da Pastilha passou para a página 11.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if i in (6,10,11,12,13,14) else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','A página 10 termina com cerca de um terço em branco; reavaliar na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s034':[1,3],'s036':[3,6],'s096':[6,9],'s097':[9,10],'s098':[11,13],'s099':[13,15]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':127,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':127,'lote':'B4-01','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':47,'casos_pendentes':12,'lotes_pendentes':3,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'B5-01','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
